  // Both headshot hosts store one id per player, so the index carries the id
  // and this rebuilds the URL. ESPN first: it is the cutout the front page's
  // faces already prefer, and the NFL copy is the fallback when ESPN 404s.
  var ESPN = 'https://a.espncdn.com/i/headshots/nfl/players/full/';
  var NFL = 'https://static.www.nfl.com/image/upload/f_auto,q_auto/league/';
  var MAX_HITS = 8;

  // Matching is done on a folded copy of the name: lower case, accents dropped,
  // punctuation gone, spaces kept. Dropping punctuation is what makes "aj"
  // find A.J. Brown and "stbrown" find nothing — keeping the space is
  // deliberate, because collapsing it would make most surnames a substring of
  // half the league.
  function fold(s) {
    var t = String(s).toLowerCase();
    if (t.normalize) t = t.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    return t.replace(/[^a-z0-9 ]+/g, '').replace(/\s+/g, ' ').trim();
  }

